function swampAddJunk(r,key,pile='discard'){const id=addBattleCard(r,{origin:SWAMP_JUNK_IDS[key]},pile);if(pile==='draw')shuffle(r.draw);return id;}
function swampQueueMod(r,e,key,count){(r.act6Reservations??=[]).push({key,count,source:e.swampId,avoid:e.act6Kind==='giant'?e.lastRootCard:null,giant:e.act6Kind==='giant'});}
function swampApplyReservations(r){const reservations=(r.act6Reservations||[]).splice(0);for(const res of reservations){let eligible=r.hand.filter(id=>C[id]&&!C[id].act6Junk&&!swampMod(r,id)&&id!==res.avoid);for(let i=0;i<res.count&&eligible.length;i++){const id=eligible.splice(Math.floor(Math.random()*eligible.length),1)[0];(r.act6Mods??={})[id]={key:res.key,turn:r.turn};if(res.giant){const e=r.enemies.find(x=>x.swampId===res.source);if(e)e.lastRootCard=id;}}}}
