function swampCardUsed(r,c,options={}){const mod=swampMod(r,c.id);if(mod&&mod.key!=='roots'){delete r.act6Mods[c.id];if(mod.key==='mud')c.act6Mud=true;}if(c.fx.selfPoison)r.poison=(r.poison||0)+c.fx.selfPoison;if(c.fx.selfWeak)r.weak=(r.weak||0)+c.fx.selfWeak;}
