function swampFoe(key,r=S.run){const [name,hp]=SWAMP_FOES[key];r.swampSerial=(r.swampSerial||0)+1;const e=Object.assign(enemy(name,swampIcon(key),hp,0),{act2:true,act6:true,act6Kind:key,swampId:'swamp-'+r.swampSerial,actionStep:0,str:0,sporeAddCount:2,sporePursuit:0});if(key==='boss')Object.assign(e,{swampPhase:'scale',petalScale:50,scaleSize:50,bloom:0,onHitJunkCount:1});return e;}
