function swampAction(e){const a={...SWAMP_FOES[e.act6Kind][2][e.actionStep%SWAMP_FOES[e.act6Kind][2].length]};if(e.act6Kind==='flower'&&a.junk)a.n=e.sporeAddCount;return a;}
function planSwamp(r){for(const e of r.enemies||[]){if(!e.act6||e.hp<=0)continue;const a=swampAction(e);e.snowAction=a;e.intent=e.hunterStun?'stunned':a.d!=null?'attack':a.b?'guard':'snowAction';e.atk=a.d||0;e.hits=a.h||1;e.guardAmount=a.b||0;}}
function prepareAct6Action(r,e){if(!e.act6)return;const a=swampAction(e);e.snowAction=a;e.atk=a.d||0;e.hits=a.h||1;e.guardAmount=a.b||0;}
