function swampDamagePhase(e){return e?.act6Kind==='boss'?e.swampPhase:null;}
function onAct6Damage(r,e,lost,attack,phase,absorbed,hpLoss){if(e?.act6Kind!=='boss'||hpLoss||e.hp<=0)return;if(phase==='scale'&&lost>0){e.petalScale=Math.max(0,e.petalScale-lost);if(e.petalScale===0){e.swampPhase='waiting';e.str++;applyHunterStun(e);}}else if(phase==='bloom'&&attack&&lost+absorbed>0){for(let i=0;i<e.onHitJunkCount;i++)swampAddJunk(r,rand(['miasma','mist','spore']),rand(['hand','draw','discard']));}}
