for(const id of hand){const c=C[id];if(!['miasma','mist'].includes(c?.act6Junk))continue;const index=r.hand.indexOf(id);if(index<0)continue;r.hand.splice(index,1);if(c.act6Junk==='miasma'&&r.hp>0)dealDamage(r,3,{damageKind:'瘴気'});exhaustCard(r,id);if(r.hp<=0)break;}
